import { Component, computed, input } from '@angular/core';
import { Tarea } from './tarea';

@Component({
  selector: 'app-tarjeta-tarea',
  template: `
    <article [class.urgente]="urgente()">
      <h3>{{ tarea().titulo }}</h3>
      <small>{{ etiqueta() }}</small>
    </article>
  `,
})
export class TarjetaTarea {
  readonly tarea = input.required<Tarea>();   // obligatorio
  readonly urgente = input(false);            // opcional, con valor por defecto
  readonly etiqueta = computed(() => this.tarea().responsable ?? 'Sin asignar');
}

